                    {
                        Title = "\ud83d\udc41\ufe0f No-show recorded",
                        Body  = $"{att.ClientName ?? "A booked client"} didn't check in for {session.ClassName} \u00b7 {session.StartTime:ddd HH:mm}",
                        Icon  = "/icons/icon-192.png",
                        Badge = "/icons/icon-192.png",
                        Url   = $"/admin/calendar?session={session.Id}",
                        Tag   = $"noshow-{attendanceId}",
                    };
                    await _notifications.PublishAsync(instructor.UserId, NotificationCategory.NoShow, payload);
                }
                catch
                {
                    // Swallow — the publisher already logs internal failures;
                    // this outer catch is for the lookup chain itself.
                }
            });
        }

