        // When a PAY_AT_STUDIO booking is marked as CHECKED_IN (arrived at studio)
        // create an UNPAID invoice if one doesn't already exist. This ensures
        // the front-desk can see the outstanding balance in the invoices table.
        if (string.Equals(status, "CHECKED_IN", StringComparison.OrdinalIgnoreCase))
        {
            _ = Task.Run(async () =>
            {
                try
                {
                    var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
                    if (att is null) return;
                    // Only auto-generate invoice for PAY_AT_STUDIO that hasn't been invoiced yet
                    if (att.PaymentMethod != "PAY_AT_STUDIO") return;
                    if (att.IsFreeClass) return;

                    // Check if invoice already exists for this attendance
                    var existingInvoice = await _invoices.Find(
                        Builders<Invoice>.Filter.ElemMatch(
                            i => i.Lines,
                            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, attendanceId)
                        )
                    ).FirstOrDefaultAsync();
                    if (existingInvoice != null) return;

                    // Resolve session for pricing
