import { db } from "../lib/db";

async function main() {
  const app = await db.app.findFirst({ where: { slug: "soul-pilates" }, include: { boards: true } })
    ?? await db.app.findFirst({ where: { name: { contains: "Soul", mode: "insensitive" } }, include: { boards: true } });
  console.log("APP:", app ? { id: app.id, name: app.name, slug: app.slug, serverId: app.serverId } : "NONE");
  const boards = app ? app.boards : await db.board.findMany({ where: { name: { contains: "Soul", mode: "insensitive" } } });
  for (const b of boards) {
    console.log("BOARD:", b.id, b.name);
    const cols = await db.boardColumn.findMany({ where: { boardId: b.id }, orderBy: { position: "asc" } });
    console.log("  COLUMNS:", cols.map((c) => `${c.name}(${c.id})`).join(" | "));
    const cards = await db.card.findMany({ where: { boardId: b.id }, include: { comments: true } });
    for (const c of cards) {
      const col = cols.find((x) => x.id === c.columnId);
      console.log(`  CARD [${col?.name}] "${c.title}" id=${c.id} type=${c.type} comments=${c.comments.length}`);
    }
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

